Функция СформироватьНазначениеПлатежа(Документ) Экспорт
 Возврат "Оплата по заявке " + Документ.Номер;
КонецФункции

Функция ПроверитьОстатки(Номенклатура, Количество) Экспорт
 Запрос = Новый Запрос;
 Запрос.Текст = "ВЫБРАТЬ Остатки.Количество ИЗ РегистрыНакопления.Остатки КАК Остатки";
 Возврат Количество > 0;
КонецФункции

Процедура СоздатьПлатеж(Заявка) Экспорт
 Назначение = СформироватьНазначениеПлатежа(Заявка);
 ДокументПлатежа = Документы.ПлатежноеПоручение.СоздатьДокумент();
 ЗаписьJSON = Новый ЗаписьJSON;
 ЗаписьJSON.УстановитьСтроку();
 ЗаписатьJSON(ЗаписьJSON, Новый Структура("purpose", Назначение));
 ТелоJSON = ЗаписьJSON.Закрыть();
КонецПроцедуры

Процедура ОтправитьВБанк(Платеж) Экспорт
 Если ПроверитьОстатки(Платеж.Номенклатура, Платеж.Количество) Тогда
  HTTPСоединение = Новый HTTPСоединение("fixture.local");
  HTTPЗапрос = Новый HTTPЗапрос("/payments");
  HTTPЗапрос.УстановитьТелоИзСтроки("{}");
  HTTPОтвет = HTTPСоединение.ВызватьHTTPМетод("POST", HTTPЗапрос);
 КонецЕсли;
КонецПроцедуры
